                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
                }

                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
                return orderShipment; // Writer로 넘김
